function prepareSessions(t){
  const fields=['draft','refs','provider','model','context','tokens'];
  const initial=Object.fromEntries(fields.map(k=>[k,t[k]]));
  const defaultProvider=initial.provider;const defaultModel=initial.model;
  t.sessionData=Object.fromEntries(t.sessions.map((_,i)=>[i,i===0?initial:{draft:'',refs:[],provider:defaultProvider,model:defaultModel,context:0,tokens:0}]));
  for(const key of fields)Object.defineProperty(t,key,{get(){if(!t.sessionData[t.session])t.sessionData[t.session]={draft:'',refs:[],provider:defaultProvider,model:defaultModel,context:0,tokens:0};return t.sessionData[t.session][key]},set(value){if(!t.sessionData[t.session])t.sessionData[t.session]={draft:'',refs:[],provider:defaultProvider,model:defaultModel,context:0,tokens:0};t.sessionData[t.session][key]=value},configurable:true});
  return t;
}
