function modelSwitchBlock(p,id){
  if(!p||!p.models.includes(id))return '模型已不可用';
  if(!p.enabled)return 'Provider 已停用';
  const capacity=p.contextWindows?.[id];
  if(!Number.isFinite(capacity)||capacity<=0)return '模型上下文上限未知，暂不能切换';
  if(!Number.isFinite(task().context))return '当前上下文占用待更新，暂不能切换';
  return task().context*1000>capacity?`当前上下文 ${windowLabel(task().context*1000)}，超过该模型 ${windowLabel(capacity)} 上限`:'';
}

