function services(){return `<div class="panel-heading"><strong>任务运行环境</strong>${button('配置','view:env','sm quiet','settings')}</div><div class="section-label between"><span>代码工作副本</span><span>${task().repos.length} 个仓库</span></div>${repoList()}<div class="section-label between"><span>本地运行</span><span>自动分配端口</span></div><div class="service-list">${task().services.map((s,i)=>s.mode==='本地'?serviceRow(s,i):'').join('')}</div><div class="section-label">远程依赖</div><div class="service-list">${task().services.map((s,i)=>s.mode==='远程'?serviceRow(s,i):'').join('')}</div><div class="routebox"><strong>请求去向 · ${esc(task().env)}</strong><div class="route"><code>saas-web</code>→<code>saas-bff</code>→<code>invoice</code>⇄<code>shipment</code></div><div style="margin-top:8px">本地依赖指向当前任务，远程数据设施共享。</div></div><div class="note">${icon('shield')} worktree、进程、端口和浏览器状态按任务独立。</div>`}
function serviceRow(s,i){return `<div class="service-row"><span class="dot ${s.running?'live':''}"></span><div class="info"><strong>${s.name}</strong><div class="endpoint">${s.mode==='本地'?`127.0.0.1:${s.port} · ${s.running?'运行中':'已停止'}`:'测试环境 · 共享'}</div></div>${i<4?`<button class="mini-toggle" data-action="service-mode:${i}" title="切换本地或远程">${s.mode} ${icon('down')}</button><button class="iconbtn" data-action="service:${i}" aria-label="${s.running?'停止':'启动'} ${s.name}">${icon(s.running?'stop':'play')}</button>`:'<span class="badge">远程</span>'}</div>`}
function browserView(){return `<div class="panel-heading"><strong>浏览器</strong><span class="badge">本任务独立登录</span></div><div class="browser-owner"><span class="flex"><span class="dot live"></span>${task().owner==='agent'?'Agent 可控制 · 当前空闲':'你正在操作 · Agent 已暂停'}</span>${button(task().owner==='agent'?'接管浏览器':'交还 Agent','takeover','sm')}</div><div class="browser-shell"><div class="browser-toolbar">${icon('left')}${icon('right')}<button class="iconbtn" data-action="browser-refresh" aria-label="刷新模拟页面">${icon('refresh')}</button><div class="urlbar">${icon('shield')} 127.0.0.1:${task().services[0].port} / SaaS</div></div>${running()?`<div class="browser-content"><div class="mock-appnav between"><span>ADBER / 订阅消费流水</span><span>测试租户</span></div><div class="invoice"><div class="between"><h3>对账单详情</h3><span class="badge live">示例</span></div><div class="kv"><span>对账单号</span><span>REC-DEMO-0920</span></div><div class="kv"><span>运单账号</span><span>测试账号 · 001</span></div><div class="kv"><span>费用项目</span><span>物流服务费</span></div><div class="kv"><span>本地查询</span><span class="accent">invoice → shipment</span></div><div class="between" style="margin-top:16px"><small>用于讨论验证界面的模拟页面</small>${button('详情','invoice-detail','sm')}</div></div></div>`:'<div class="empty-browser">本地前端尚未启动<br><br>'+button('启动本地服务','toggle-run','primary','play')+'</div>'}</div><div class="toolbar-space between"><strong style="font-size:11px">验证记录</strong>${button(task().verified?'重新模拟验证':'模拟页面验证','verify','sm', 'play')}</div><div class="snapshot"><div>${task().verified?'✓ 示例请求成功 · 详情已显示':'○ 等待本任务页面验证'}</div><div class="mono">BFF → invoice:${task().services[2].port} → shipment:${task().services[3].port}</div><div>Cookie / 本地存储：仅属于 ${esc(task().slug)}</div></div><div class="note">此页面仅用于 UI 讨论，尚未连接真实业务服务。</div>`}
function filesView(){return (taskDirectories().length?directoryRootChoices():'')+ `<div class="panel-heading"><strong>文件与变更</strong><span class="badge">+24 −6</span></div>${repoList()}<div class="section-label">${repos[state.fileRepo]} / 示例文件</div><div class="file-layout"><div class="filetree"><div>▾ src</div><button class="filebutton active" data-action="file-open">　detail.ts</button><div>▸ configs</div><div>▸ .vscode</div><div>　 README.md</div></div><div><div class="codeblock">// UI 示例，非业务源码\n- account: response.account\n+ account: response.account\n+   ?? await loadAccount(id)\n\n  return {\n    ...detail,\n+   shipmentAccount: account\n  }</div>${button('引用所选代码','quote-code','sm','chat')}</div></div><div class="note">仓库：${repos[state.fileRepo]}<br>目录：<span class="mono">${esc(workspacePath(task().workspaceRoot,task().workspaceKey,repos[state.fileRepo]))}</span><br>分支：task/${esc(task().slug)} · 当前任务独立 worktree${task().repoBases[state.fileRepo]?`<br>创建基线：${esc(task().repoBases[state.fileRepo].ref)} @ ${esc(task().repoBases[state.fileRepo].head)}（模拟提交）`:""}</div><div class="toolbar-space">${button('审阅与交付','delivery','sm','branch')}</div>`}
function terminalView(){return (taskDirectories().length?directoryRootChoices():'')+ `<div class="panel-heading"><strong>终端 · ${repos[state.fileRepo]}</strong><span class="badge">任务内会话</span></div><div class="terminal"><span style="color:#6c7ea7">➜</span> task/${esc(task().slug)}\n\n[PiDock] 已解析任务环境\n[PiDock] 模板 ${task().version} · ${esc(task().env)}\n\n${task().services.filter(s=>s.mode==='本地').map(s=>`${s.running?'✓':'○'} ${s.name.padEnd(19,' ')} :${s.port} ${s.running?'ready':'stopped'}`).join('\n')}\n\n<span class="muted">原型终端：输入仅回显，不执行命令。</span>\n<div id="terminal-output"></div><span style="color:#6c7ea7">$</span> <input id="terminal-input" aria-label="模拟终端命令" placeholder="试试输入 pwd"></div><div class="note">人工终端与 Agent 共用任务执行权。${sessionReadonly()?'当前为只读会话，终端不可执行。':'输入回车可模拟接管提示。'}</div>`}
function logsView(){return `<div class="panel-heading"><strong>运行日志</strong><span class="badge">示例记录</span></div>${task().services.filter(s=>s.mode==='本地').map(s=>`<div class="logline"><span class="accent">10:25:01</span> [${s.name}] ${s.running?'listening at :'+s.port:'process stopped'}</div>`).join('')}<div class="logline">10:25:02 [routes] local task bindings resolved</div><div class="logline">10:25:03 [account-service] remote test environment</div><div class="note">日志中会显示服务、所属运行实例和错误；这里仅展示信息布局。</div>`}
function panel(){if((directoryTask()||selectedDirectory())&&['files','terminal'].includes(state.tab))return directoryPanel();if(!task().services.length&&['services','browser','logs'].includes(state.tab))return '<div class="empty">尚未配置本地服务。可在环境与服务中按需添加。</div>';return state.tab==='browser'?browserView():state.tab==='files'?filesView():state.tab==='terminal'?terminalView():state.tab==='logs'?logsView():services()}
function workbench(){if(!task().openTools?.length)return '';state.tab=task().activeTool;return `<section class="workbench" aria-label="任务工具面板"><div class="work-tabs">${task().openTools.map(key=>{const [,ic,label]=toolItems.find(t=>t[0]===key);return `<div class="open-tool-tab ${state.tab===key?'active':''}"><button class="work-tab" data-action="tab:${key}">${icon(ic)}${label}</button><button class="tab-close" data-action="close-tool:${key}" aria-label="关闭${label}" title="关闭${label}">${icon('close')}</button></div>`}).join('')}<button class="iconbtn collapse-tools" data-action="close-tools" aria-label="收起工具区" title="收起工具区">${icon('close')}</button></div><div class="work-content">${panel()}</div></section>`}

function VariantA(){if(directoryTask())return directoryWorkspace();return `<div class="taskbody ${task().openTools?.length?'':'tools-closed'}">${conversation()}${workbench()}</div>`}
function VariantB(){if(directoryTask())return directoryWorkspace();return `<div class="runtime-layout"><div class="runtime-overview"><section><div class="between rowgap"><div><h2>先让环境跑起来</h2><small>当前任务的本地服务和依赖去向</small></div><span class="badge live">${running()} / ${localCount()} 就绪</span></div><div class="service-cards">${(task()?.services||serviceSeed.filter(s=>currentProject().repos.includes(s.repo))).slice(0,4).map((s,i)=>`<div class="service-card"><div class="between"><h3>${s.name}</h3><span class="dot ${s.running?'live':''}"></span></div><small>${repos[s.repo]}</small><div class="port">${s.mode==='本地'?'127.0.0.1:'+s.port:'测试环境 · 远程'}</div><div class="between"><button class="mini-toggle" data-action="service-mode:${i}">${s.mode} ${icon('down')}</button>${button(s.running?'停止':'启动','service:'+i,'sm',s.running?'stop':'play')}</div></div>`).join('')}</div><div class="routebox"><strong>本地调用链</strong><div class="route"><code>web</code>→<code>BFF</code>→<code>invoice</code>⇄<code>shipment</code></div><div class="note">账号服务、Redis、PostgreSQL 使用测试环境。</div></div><div class="runtime-section"><div class="runtime-subnav">${[['services','仓库'],['browser','浏览器验证'],['files','代码变更'],['terminal','终端'],['logs','日志']].map(([k,l])=>button(l,'tab:'+k,state.tab===k?'sm primary':'sm')).join('')}</div>${workbench()}</div></section>${conversation()}</div></div>`}
function VariantC(){if(directoryTask())return directoryWorkspace();return `<div class="focus-layout"><section class="focus-main"><div class="journey">${['准备代码','运行环境','浏览器验证','审阅交付'].map((s,i)=>`<button class="${state.step===i?'active':''}" data-action="step:${i}"><span class="step-num">${i+1}</span>${s}</button>`).join('')}</div>${task().openTools?.length?workbench():`<div class="on-demand-empty"><span class="brandmark">π</span><h2>需要时，再展开工作区</h2><p>浏览器、文件和终端随时可以打开。</p><div class="flex">${button('打开浏览器','tab:browser','','globe')}${button('浏览文件','tab:files','','folder')}${button('打开终端','tab:terminal','','terminal')}</div></div>`}</section>${conversation()}</div>`}

function projectPage(){return managementProjectPage()}
const seedEnvRows=[['PORT','3001','服务端口'],['INVOICE_SERVICE_ENDPOINT','127.0.0.1:9001','本地 invoice'],['SHIPMENT_SERVICE_V1_ENDPOINT','127.0.0.1:9002','本地 shipment'],['DATABASE_PASSWORD','••••••••••••','本机凭据引用'],['NODE_ENV','test','共享环境模板']];
function envPage(){return managedEnvironmentPage()}
function environmentEditor(){const draft=environmentDraft();state.envDirty=draft.dirty;const labels={task:'任务覆盖',shared:'共享模板',private:'本机私有配置'};return `<div class="page"><div class="between"><div><div class="view-label">ENVIRONMENTS</div><h1>环境与服务</h1></div><div class="flex">${button('管理环境','environments')}${button('新增环境','new-environment','primary','plus')}${task()?button('从 .vscode 导入','import-config','','folder'):''}</div></div><p class="page-intro">继续使用仓库默认配置，通过环境变量调整服务运行方式。</p><div class="between config-toolbar"><div class="flex"><select id="environment-select" aria-label="环境">${currentProject().environments.map(e=>`<option value="${e.id}" ${state.envId===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select><span class="badge">共享模板 v${currentEnvironment().version}</span></div>${task()&&task().envId===state.envId?button('查看模板更新','template-update','sm'):''}</div><div class="tabs">${Object.entries(labels).filter(([k])=>(task()&&task().envId===state.envId)||k!=='task').map(([k,v])=>`<button class="${state.envScope===k?'active':''}" data-action="scope:${k}">${v}</button>`).join('')}</div>${state.envScope==='task'?`<div class="inline-notice">当前任务：${esc(task().name)} · 覆盖只作用于该任务。自动地址在分配端口后解析。</div>`:state.envScope==='shared'?'<div class="inline-notice">共享模板可版本管理。保存前预览差异；已有任务保留采用的版本。</div>':'<div class="inline-notice">本机凭据与路径单独保存，敏感值不进入共享模板。</div>'}<div class="between rowgap"><h3>${labels[state.envScope]} <span class="muted">/ ${esc(state.env)}</span></h3><span class="flex">${button(state.envDirty?'保存更改 · 未保存':'保存更改','save-env','sm primary')}</span></div>${environmentTable()}<div class="note">直接编辑 KEY 和 VALUE；VALUE 可以为空。当前标签决定配置作用范围，任务覆盖不会改写共享模板。</div><div class="between toolbar-space rowgap"><h2>服务启动配方</h2>${button('添加服务','service-recipe','sm','plus')}</div><div class="grid2">${currentEnvironment().services.map((s,i)=>`<div class="card"><div class="between"><h3>${s.name}</h3>${button('编辑','recipe:'+i,'sm quiet','settings')}</div><small>${repos[s.repo]} · ${i<2?'Node.js':'Go'}</small><div class="mono toolbar-space muted">${i<2?'使用项目脚本启动':'读取仓库默认 config.yaml'}</div></div>`).join('')}</div></div>`}
function providersPage(){return `<div class="page"><div class="between"><div><div class="view-label">MODELS</div><h1>模型与 Provider</h1></div>${button('添加 Provider','add-provider','primary','plus')}</div><p class="page-intro">保存多个服务账号，在对话中按需切换。凭据只保存在本机。</p><div class="grid3">${state.providers.map((p,i)=>`<div class="provider-card"><div class="between"><div class="provider-symbol">${i===0?'✳':i===1?'◎':'↗'}</div><span class="badge ${p.enabled?'live':''}">${p.enabled?'已启用':'已停用'}</span></div><h3 class="toolbar-space">${esc(p.name)}</h3><div style="margin-top:7px"><span class="badge">${esc(protocolLabel(p.protocol))}</span></div><p class="mono" style="overflow-wrap:anywhere">${esc(p.endpoint)}</p><div class="provider-model-chips">${p.models.map(m=>`<span class="badge">${esc(modelDetail(p,m).name)} · ${windowLabel(p.contextWindows?.[m])}${modelDetail(p,m).input.includes('image')?' · 图片':''}</span>`).join('')}</div><small>${p.models.length} 个模型 · 凭据已设置（模拟）</small><div class="between toolbar-space">${button('编辑','provider:'+i,'sm')}${task()?button('选择模型','use-provider:'+i,'sm '+(task().provider===i?'quiet':'primary')):'<small>在任务会话中选择</small>'}</div></div>`).join('')}</div><div class="card toolbar-space"><h3>切换只影响当前会话</h3><p class="page-intro" style="margin:8px 0 0">保留对话历史与工具结果。执行中切换会等待当前回合结束；累计 Token 仍按实际调用的 Provider 记录。</p></div></div>`}
function usagePage(){if(!task())return '<div class="page"><h1>Token 用量</h1><div class="empty">当前项目还没有可查看用量的任务。</div></div>';const total=task().tokens.toFixed(1);return `<div class="page"><div class="between"><div><div class="view-label">USAGE</div><h1>Token 用量</h1></div><div class="flex usage-controls"><select id="usage-range" aria-label="统计日期">${['近 7 天','今天','近 30 天'].map(x=>`<option ${state.usageRange===x?'selected':''}>${x}</option>`).join('')}</select><select id="usage-group" aria-label="统计维度">${['Provider','项目','任务','会话','模型'].map(x=>`<option ${state.usageGroup===x?'selected':''}>${x}</option>`).join('')}</select></div></div><p class="page-intro">按实际调用累计，压缩上下文不会减少消耗。以下均为示例统计。</p><div class="grid4"><div class="card"><small>累计 Token</small><div class="stat">${state.usageRange==='今天'?'248k':state.usageRange==='近 30 天'?'4.82M':'1.28M'}</div><small>包含已报告的缓存用量</small></div><div class="card"><small>当前会话</small><div class="stat">${total}<small> k</small></div><small>${esc(task().sessions[task().session])}</small></div><div class="card"><small>已记录调用</small><div class="stat">${state.usageRange==='今天'?'38':'186'}</div><small>按独立调用去重</small></div><div class="card"><small>未完整报告</small><div class="stat">3 <small>次</small></div><small>未知用量不按零计算</small></div></div><div class="grid2 toolbar-space"><div class="card"><div class="between"><h3>每日消耗</h3><small>${state.usageRange}</small></div><div class="bar-chart">${[32,58,41,80,64,95,70].map((v,i)=>`<div class="bar-column"><span class="bar" style="height:${v}%"></span><small>09/${14+i}</small></div>`).join('')}</div></div><div class="card"><h3>Token 构成</h3><div class="flex" style="justify-content:space-around;margin-top:22px"><div class="usage-donut"></div><div style="font-size:11px;line-height:2.4">● 输入 <strong>678k</strong><br><span style="color:#929db6">●</span> 缓存读取 <strong>448k</strong><br><span style="color:#d0d4de">●</span> 输出 <strong>154k</strong></div></div></div></div><div class="between toolbar-space rowgap"><h2>按${state.usageGroup}汇总</h2><span class="badge">示例 · 不代表账单</span></div><div class="table-wrap"><table class="table"><tr><th>${state.usageGroup}</th><th>输入</th><th>输出</th><th>缓存读取</th><th>总计</th><th>完整性</th></tr>${(state.usageGroup==='Provider'?['Anthropic · 工作账号','OpenAI · 个人账号','团队网关']:state.usageGroup==='任务'?projectTasks().map(t=>t.name):state.usageGroup==='会话'?task().sessions:state.usageGroup==='项目'?[currentProject().name]:['Claude Sonnet','GPT','团队模型']).map((p,i)=>`<tr><td>${esc(p)}</td><td class="mono">${[420,210,48][i%3]}k</td><td class="mono">${[98,42,14][i%3]}k</td><td class="mono">${[280,145,23][i%3]}k</td><td class="mono">${[798,397,85][i%3]}k</td><td><span class="badge ${i===2?'warn':'live'}">${i===2?'部分未报告':'已报告'}</span></td></tr>`).join('')}</table></div></div>`}
function archivePage(){return `<div class="page"><h1>已归档</h1><p class="page-intro">归档停止运行并保留代码、会话和浏览器状态；清理是另一个操作。</p>${projectTasks().some(t=>t.archived)?state.tasks.map((t,i)=>t.projectId===state.projectId&&t.archived?`<div class="card between"><div><h3>${esc(t.name)}</h3><small>${t.workspaceMode==='directory'?'普通目录':t.repos.length+' 个仓库'} · 会话与浏览器状态已保留</small></div><div class="flex">${button('恢复','restore:'+i,'sm')}${button('清理…','cleanup:'+i,'sm')}</div></div>`:'').join(''):'<div class="empty">还没有归档任务。可从任务右上角的「···」菜单体验归档。</div>'}</div>`}
function switcher(){return `<div class="switcher" aria-label="布局比较"><button data-action="variant-prev" aria-label="上一个布局">←</button><span class="switch-label">布局探索</span>${[['A','对话优先'],['B','运行优先'],['C','验证优先']].map(([v,n])=>`<button class="${state.variant===v?'active':''}" data-action="variant:${v}">${v} · ${n}</button>`).join('')}<button data-action="variant-next" aria-label="下一个布局">→</button><span class="sep"></span><span class="state">${task()?esc(task().slug||task().name)+' · '+running()+' 服务 · '+(task().owner==='agent'?'Agent':'人工'):esc(currentProject()?.name||'未选择项目')}</span><button data-action="guide">导览</button></div>`}
function render(){if(state.view==='task'&&!task())state.view='project';closeComposerPopover();state.completion=[];const pages={project:projectPage,env:envPage,providers:providersPage,usage:usagePage,schedules:schedulesPage,capabilities:capabilitiesPage,remote:remoteAccessPage,archive:archivePage};document.querySelector('#app').innerHTML=`<div class="app variant-${state.variant}">${sidebar()}<main class="main">${topbar()}${state.view==='task'?header()+(task().subagentPanelOpen?subagentWorkspace():({A:VariantA,B:VariantB,C:VariantC}[state.variant])()):(pages[state.view]||projectPage)()}</main></div>${switcher()}`;decorateClosure();const msgs=document.querySelector('.messages');if(msgs&&task()?.messages.length)msgs.scrollTop=msgs.scrollHeight}
function modal(title,body,footer=''){closeComposerPopover();document.querySelector('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header between"><h2>${title}</h2><button class="iconbtn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></header><div class="modal-body">${body}</div><footer class="modal-footer"><small>UI 草稿 · 操作仅在内存中模拟</small><div class="flex">${button('取消','close-modal')}${footer}</div></footer></section></div>`;document.querySelector('.modal input')?.focus()}
function closeModal(){document.querySelector('#overlay').innerHTML=''}
function workspaceSettingsDialog(){modal('本机设置',`<div class="formfield"><label>应用配置目录</label><code class="config-path">~/.pi/dock</code><small>默认配置文件：~/.pi/dock/config.json（Windows：用户主目录下的 .pi\\dock）。<br>用于应用本机设置；项目共享模板仍保存在项目中，凭据使用安全存储引用。</small></div><div class="formfield"><label for="workspace-root-setting">默认任务根目录</label><input id="workspace-root-setting" value="${esc(state.workspaceRoot)}" placeholder="例如：D:\&#92;PiDockTasks"><small>新任务会在这个位置创建独立文件夹。修改后只影响后续新任务，已有任务不迁移。</small></div><div class="preview-note">目录属于本机设置，不写入项目共享模板。原型仅保存输入，不检查磁盘或创建目录。</div>`,button('保存设置','save-workspace-settings','primary'))}
function updateWorkspacePreview(){const input=document.querySelector('#task-root');const preview=document.querySelector('#task-path-preview');if(input&&preview)preview.textContent=input.value.trim()?workspacePath(input.value.trim(),pendingWorkspaceKey):'请填写任务根目录';updateTaskEntryPreview()}
function taskDialog(add=false,initialType='normal'){
  if(!currentProject()){projectsDialog();return}
  if(!currentProject().repos.length&&!projectDirectories().length){toast('请先添加项目目录');projectDialog(currentProject().id);return}
  pendingWorkspaceKey=add?task().workspaceKey:newWorkspaceKey();
  modal(add?'为任务添加目录':'新建任务',`${!add?`${taskTypePicker(initialType)}<div class="formfield"><label for="task-name">任务名称</label><input id="task-name" placeholder="例如：修复账单金额展示"><small>支持中文，仅作为显示名称，不用于文件夹命名。</small></div><div class="git-task-fields"><div class="grid2"><div class="formfield"><label for="new-env">环境</label><select id="new-env"><option value="">暂不使用环境</option>${currentProject().environments.map(e=>`<option value="${e.id}" ${e.id===state.envId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="formfield"><label for="task-branch">任务分支</label><input id="task-branch" value="task/${pendingWorkspaceKey.slice(5)}"></div></div></div><div class="formfield"><label for="task-root">任务根目录</label><input id="task-root" value="${esc(state.workspaceRoot)}"><small>来自本机设置，可为本次任务修改。仅选普通目录时也会创建任务文件夹。</small></div><div id="new-task-schedule">${initialType==='scheduled'?scheduledTaskFields():''}</div>`:`<p class="page-intro">Git 仓库建立工作副本，普通目录添加软链接；沿用当前任务文件夹。</p>`}
  <div class="between"><h3>选择代码仓库</h3><small>远程基线分支</small></div><div class="newtask-list">${repos.map((r,i)=>{if(!currentProject().repos.includes(i))return '';const existing=add&&task().repos.includes(i);return `<div class="check-row"><input type="checkbox" name="repo" aria-label="选择 ${r}" value="${i}" ${existing?'checked disabled':!add?'checked':''}><span>${r}${existing?' <small>已加入</small>':''}</span><input class="branch" data-repo="${i}" aria-label="${r} 远程基线分支" value="${esc(existing?(task().repoBases[i]?.ref||'origin/main'):'origin/main')}" ${existing?'disabled':''}></div>`}).join('')}</div>
  ${taskDirectoryChoices(add)}<div class="baseline-policy"><strong>创建前获取远程最新提交</strong><small>先获取所选分支的最新提交，再创建独立分支和工作副本。获取失败会保留表单，重试成功后再继续；不会使用旧基线。${add?'仅获取本次新选的仓库。':''}</small></div>
  <div class="workspace-preview"><div class="between"><strong>任务文件夹 · pi 工作目录</strong><small>${add?'沿用当前目录':'自动生成 · 英文与数字'}</small></div><code id="task-path-preview">${esc(workspacePath(add?task().workspaceRoot:state.workspaceRoot,pendingWorkspaceKey))}</code><div id="task-entry-preview"></div><small>pi 从此目录启动，通过子目录访问 worktree 和普通目录。名称仅作显示，不影响路径。</small></div>
  <details class="task-preview-scenario"><summary>原型演示场景</summary><label for="task-fetch-scenario">远程获取结果</label><select id="task-fetch-scenario"><option value="success">获取成功（模拟）</option><option value="failure">第一个所选仓库获取失败（模拟）</option></select></details><div id="task-prepare-error" role="alert"></div>`,button(add?'获取最新基线并添加':'获取最新基线并创建',add?'confirm-addrepo':'confirm-newtask','primary'));
  document.querySelector('.modal').classList.add('task-editor');refreshTaskDirectoryForm();
}
function confirmTask(add=false){
  const selected=[...document.querySelectorAll('input[name=repo]:checked')].map(e=>+e.value);
  const indices=add?selected.filter(i=>!task().repos.includes(i)):selected;
  const name=add?task().name:document.querySelector('#task-name').value.trim();
  const taskType=add?task().taskType:(document.querySelector('input[name=task-type]:checked')?.value||'normal');
  const scheduleDraft=!add&&taskType==='scheduled'?readScheduledTaskDraft():null;
  const root=add?task().workspaceRoot:document.querySelector('#task-root').value.trim();
  const directories=[...document.querySelectorAll('input[name=task-directory]:checked:not(:disabled)')].map(el=>projectDirectories().find(d=>d.id===el.value)).filter(Boolean);
  if(!name||(!indices.length&&!directories.length)){toast(add?'请选择要追加的仓库或目录':'请填写任务名称，并选择至少一个仓库或目录');return}
  if(scheduleDraft&&!validateScheduledTaskDraft(scheduleDraft))return;
  if(!validWorkspaceRoot(root)){toast('请填写完整的任务根目录，例如 /Users/name/Tasks 或 D:\\Tasks');return}
  const bases=Object.fromEntries(indices.map(i=>[i,{ref:document.querySelector(`.branch[data-repo="${i}"]`).value.trim(),head:['a42c91e','7bd210a','8c314fd','3f98b12'][i]}]));
  if(Object.values(bases).some(b=>!/^[-A-Za-z0-9_]+\/[^\s]+$/.test(b.ref))){toast('请填写远程名称和分支，例如 origin/main 或 upstream/release/v2');return}
  if(indices.length&&document.querySelector('#task-fetch-scenario').value==='failure'){
    document.querySelector('#task-prepare-error').innerHTML=`<div class="inline-notice">${esc(repos[indices[0]])}：无法获取 ${esc(bases[indices[0]].ref)}（模拟连接失败）。<br>尚未创建工作副本；已填写内容保留。${button('重试获取',add?'retry-addrepo':'retry-newtask','sm')}</div>`;return;
  }
  if(add){task().repos=[...task().repos,...indices];Object.assign(task().repoBases,bases);task().directories=[...taskDirectories(),...snapshotTaskDirectories(directories)];task().workspaceMode=task().repos.length?'git':'directory'}else{
    const slug=document.querySelector('#task-branch').value.trim().replace(/^task\//,'')||pendingWorkspaceKey.slice(5);
    const t=prepareSessions(makeTask(name,slug,false,indices));Object.assign(t,{workspaceKey:pendingWorkspaceKey,workspaceRoot:root,repoBases:bases,isNew:true,context:0,tokens:0,taskType});
    const selectedEnv=indices.length?currentProject().environments.find(e=>e.id===document.querySelector('#new-env').value):null;
    Object.assign(t,{projectId:state.projectId,directories:snapshotTaskDirectories(directories),workspaceMode:indices.length?'git':'directory',envId:selectedEnv?.id||null,env:selectedEnv?.name||'无需环境',version:selectedEnv?'v'+selectedEnv.version:''});
    if(!selectedEnv||!indices.length)t.services=[];else t.services.forEach(s=>{if(s.port)s.port+=state.tasks.length*100;s.mode=s.repo!==undefined&&!indices.includes(s.repo)?'远程':s.mode});
    state.tasks.push(t);state.task=state.tasks.length-1;if(scheduleDraft)attachScheduleToTask(t,state.task,scheduleDraft);state.envId=t.envId;state.env=t.env;state.fileRepo=indices[0];state.view='task';
  }
  closeModal();render();toast(indices.length?'已模拟准备任务目录：worktree 与软链接':'已模拟创建任务目录与软链接，未写入磁盘');
}
function modelDialog(providerIndex){if(state.view==='task'&&providerIndex===undefined){openModelPicker();return}modal('选择 Provider 与模型',`<p class="page-intro">在同一 Provider 下切换模型，或选择其他 Provider。当前会话保留历史。</p>${state.providers.map((p,i)=>providerIndex!==undefined&&i!==providerIndex?'':`<div class="model-provider-group"><div class="between"><strong>${esc(p.name)}</strong><small>${esc(protocolLabel(p.protocol))}</small></div>${p.models.map((m,j)=>`<button class="check-row model-option" data-action="select-model:${i}:${j}" ${modelSwitchBlock(p,m)?'disabled':''} title="${esc(modelSwitchBlock(p,m))}"><span class="dot ${task().provider===i&&task().model===m?'live':''}"></span><span style="flex:1">${esc(modelDetail(p,m).name)}<br><small>${esc(m)}${modelDetail(p,m).input.includes('image')?' · 支持图片':' · 仅文本'}</small>${modelSwitchBlock(p,m)?`<span class="model-switch-block">${esc(modelSwitchBlock(p,m))}</span>`:''}</span><small>${windowLabel(p.contextWindows?.[m])} 上下文 / ${windowLabel(modelDetail(p,m).maxTokens)} 输出</small>${task().provider===i&&task().model===m?'<span class="badge live">当前</span>':icon('right')}</button>`).join('')}</div>`).join('')}`)}
function thinkingSettings(d){const mode=d.thinkingMode||'auto';const levels=d.thinkingLevels?.length?d.thinkingLevels:['low','medium','high'];return `<div class="thinking-settings"><label><span>推理能力</span><select class="provider-thinking-mode" aria-label="推理能力">${[['auto','跟随模型目录（推荐）'],['none','不支持推理'],['custom','自定义可用档位']].map(([key,label])=>`<option value="${key}" ${mode===key?'selected':''}>${label}</option>`).join('')}</select></label><div class="thinking-custom" ${mode==='custom'?'':'hidden'}><p class="model-limit-help">只勾选服务实际支持的档位；不可关闭思考的模型，不勾选 off。</p><div class="thinking-levels">${reasoningLevels.map(([key,label])=>`<label><input class="provider-thinking-level" type="checkbox" value="${key}" ${levels.includes(key)?'checked':''}><span>${label} <small>${key}</small></span></label>`).join('')}</div><label class="thinking-default-field"><span>该模型默认档位</span><select class="provider-thinking-default" aria-label="默认推理档位">${levels.map(key=>`<option value="${key}" ${key===(d.thinkingDefault||'medium')?'selected':''}>${reasoningLabel(key)} · ${key}</option>`).join('')}</select></label><details class="thinking-advanced"><summary>高级：服务参数映射</summary><p class="model-limit-help">留空使用 pi 默认映射；只在服务使用不同参数值时填写。不支持的档位会明确禁用。</p>${reasoningLevels.map(([key,label])=>`<label class="thinking-map-row"><span>${label} · ${key}</span><input class="provider-thinking-map" data-level="${key}" aria-label="${key} 参数映射" value="${esc(d.thinkingMap?.[key]||'')}" placeholder="使用 pi 默认映射" ${levels.includes(key)?'':'disabled'}></label>`).join('')}</details></div><p class="thinking-auto-note model-limit-help" ${mode==='auto'?'':'hidden'}>正式接入从模型目录和 pi 获取可用档位；未知模型需要补充配置，不推断为全部支持。</p></div>`}
function syncThinking(row){const mode=row.querySelector('.provider-thinking-mode').value;row.querySelector('.thinking-custom').hidden=mode!=='custom';row.querySelector('.thinking-auto-note').hidden=mode!=='auto';const levels=[...row.querySelectorAll('.provider-thinking-level:checked')].map(el=>el.value);const select=row.querySelector('.provider-thinking-default');const previous=select.value;select.innerHTML=levels.map(key=>`<option value="${key}">${reasoningLabel(key)} · ${key}</option>`).join('');if(levels.includes(previous))select.value=previous;for(const input of row.querySelectorAll('.provider-thinking-map'))input.disabled=!levels.includes(input.dataset.level);}
function thinkingKey(){return task().session+':'+task().provider+':'+task().model}
function effectiveThinking(){const d=selectedModelDetail();const saved=task().thinkingSelections?.[thinkingKey()];return saved===undefined?d.thinkingDefault:(d.thinkingLevels.includes(saved)?saved:'')}
function thinkingControl(){const d=selectedModelDetail();if(d.thinkingMode==='none')return '';if(d.thinkingMode==='custom'&&d.thinkingLevels.length===1)return `<span class="model-trigger" title="此模型仅支持一个推理档位">推理 · ${reasoningLabel(d.thinkingLevels[0])}（固定）</span>`;return `<button class="model-trigger thinking-trigger" data-action="thinking" aria-haspopup="dialog" aria-expanded="false" title="推理档位">${d.thinkingMode==='custom'?'推理 · '+(reasoningLabel(effectiveThinking())||'待选择'):'推理 · 跟随模型'} ${icon('down')}</button>`}
function thinkingDialog(){
  const d=selectedModelDetail();
  const body=d.thinkingMode==='custom'?`<p class="popover-help">${esc(d.name)} · 仅用于当前会话</p><div class="thinking-options">${d.thinkingLevels.map(key=>`<button class="picker-choice" data-action="set-thinking:${key}" aria-pressed="${effectiveThinking()===key}"><span>${reasoningLabel(key)} <small>${key}</small></span><span class="flex">${key===d.thinkingDefault?'<small>模型默认</small>':''}${effectiveThinking()===key?icon('check'):''}</span></button>`).join('')}</div>`:`<p class="popover-help">当前模型跟随模型目录，尚未获取可用档位。</p><p class="popover-help">可到模型设置中配置可用档位。本原型尚未连接模型目录。</p>`;
  composerPopover('thinking','推理档位',body+`<div class="popover-footer">${button('模型设置','current-model-settings','sm')}</div>`);
}
// Conversation controls are draft UI; all selections and usage remain local samples.
function closeComposerPopover(restore=false){
  const panel=document.querySelector('#composer-popover');if(!panel)return;
  const action=panel.dataset.anchor;panel.remove();
  const trigger=document.querySelector('.composer-wrap [data-action="'+action+'"]');trigger?.setAttribute('aria-expanded','false');if(restore)trigger?.focus();
}
function composerPopover(action,title,body){
  const trigger=document.querySelector('.composer-wrap [data-action="'+action+'"]');if(!trigger)return;
  const same=document.querySelector('#composer-popover')?.dataset.anchor===action;closeComposerPopover();if(same)return;
  const panel=document.createElement('section');panel.id='composer-popover';panel.className='composer-popover';panel.dataset.anchor=action;panel.setAttribute('role','dialog');panel.setAttribute('aria-label',title);
  panel.innerHTML=`<header class="between"><strong>${title}</strong><button class="iconbtn" data-action="close-composer-popover" aria-label="关闭浮层">${icon('close')}</button></header>${body}`;
  document.body.appendChild(panel);trigger.setAttribute('aria-expanded','true');
  const rect=trigger.getBoundingClientRect(),width=Math.min(action==='model'?390:340,innerWidth-24);
  panel.style.width=width+'px';panel.style.left=Math.max(12,Math.min(['context','permissions'].includes(action)?rect.left:rect.right-width,innerWidth-width-12))+'px';
  const above=rect.top-20,below=innerHeight-rect.bottom-20;
  panel.style.maxHeight=Math.max(120,Math.max(above,below))+'px';
  if(above>=below)panel.style.bottom=(innerHeight-rect.top+8)+'px';else panel.style.top=(rect.bottom+8)+'px';
  panel.querySelector('input')?.focus();
  if(!panel.querySelector('input'))panel.querySelector('[aria-pressed="true"],.picker-choice,.iconbtn')?.focus();
}
function modelPickerRows(query=''){
  const q=query.trim().toLowerCase();
  const groups=state.providers.map((p,i)=>{
    const models=p.models.map((m,j)=>({id:m,index:j,detail:modelDetail(p,m)})).filter(m=>(p.name+' '+m.id+' '+m.detail.name).toLowerCase().includes(q));
    if(!models.length)return '';
    return `<div class="picker-provider"><div class="between"><strong>${esc(p.name)}</strong><small>${p.enabled?models.length+' 个模型':'已停用'}</small></div>${models.map(({id,index,detail})=>`<button class="picker-choice model-picker-choice" data-action="select-model:${i}:${index}" aria-pressed="${task().provider===i&&task().model===id}" ${modelSwitchBlock(p,id)?'disabled':''} title="${esc(modelSwitchBlock(p,id))}"><span class="model-picker-info"><strong>${esc(detail.name)}</strong>${detail.name!==id?`<span class="model-picker-id">${esc(id)}</span>`:''}<small>${windowLabel(p.contextWindows?.[id])} 上下文 · ${detail.input.includes('image')?'支持图片':'仅文本'}</small>${modelSwitchBlock(p,id)?`<span class="model-switch-block">${esc(modelSwitchBlock(p,id))}</span>`:''}</span>${task().provider===i&&task().model===id?icon('check'):''}</button>`).join('')}</div>`;
  }).join('');
  return groups||'<div class="picker-empty">没有匹配的模型<br><small>试试其他名称或 Provider</small></div>';
}
function openModelPicker(){composerPopover('model','选择模型',`<input id="conversation-model-search" aria-label="搜索模型或 Provider" placeholder="搜索模型或 Provider…" autocomplete="off"><div id="conversation-model-results">${modelPickerRows()}</div><div class="popover-footer between"><small>当前上下文 ${Number.isFinite(task().context)?task().context.toFixed(1)+'k':'待更新'} · 估算</small>${button('管理模型','manage-models','sm')}</div>`);}
function contextDialog(){
  const capacity=modelWindow(),pct=capacity>0?contextPercent():null;
  composerPopover('context','上下文占用',`<div class="context-summary"><strong>${pct===null?'未知':pct.toFixed(1)+'%'}</strong><span>${task().context.toFixed(1)}k / ${windowLabel(capacity)} Tokens <small>估算</small></span></div><div class="context-track"><i style="width:${Math.min(100,pct||0)}%"></i></div><div class="context-model"><strong>${esc(selectedModelDetail().name)}</strong><small>${esc(state.providers[task().provider].name)}</small></div><p class="popover-help">包含消息、指令和工具结果。压缩可以释放上下文空间，累计 Token 消耗会保留。</p><div class="context-total between"><span>本会话累计消耗</span><strong>${task().tokens.toFixed(1)}k Tokens</strong></div><div class="popover-footer between"><small>原型示例数据</small>${button('模拟压缩','compact','sm')}</div>`);
}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#composer-popover,.composer-wrap [data-action="model"],.composer-wrap [data-action="thinking"],.composer-wrap [data-action="context"],.composer-wrap [data-action="permissions"]'))closeComposerPopover();});
window.addEventListener('resize',()=>closeComposerPopover());
// Model discovery is a local interaction sample; no provider requests are sent.
let providerCatalog=[],modelPickerId=0;
function syncModelName(row){const name=row.querySelector('.provider-model-name');if(name.dataset.autoName==='true')name.value=row.querySelector('.provider-model-id').value;}
function closeModelCandidates(){for(const list of document.querySelectorAll('.model-candidates')){list.hidden=true;const input=list.closest('.model-id-field').querySelector('input');input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}}
function resetModelCatalog(){providerCatalog=[];closeModelCandidates();document.querySelector('#model-sync-status').textContent='连接设置已更改，请重新同步；仍可直接填写模型 ID。';}
function syncModelCatalog(){
  const endpoint=document.querySelector('#provider-url').value.trim();
  if(!endpoint){toast('请先填写服务地址');return}
  const samples={'anthropic-messages':['claude-sonnet-demo','claude-opus-demo','claude-haiku-demo'],'openai-responses':['gpt-demo','gpt-mini-demo','reasoning-demo'],'openai-chat-completions':['team-chat-demo','team-reasoning-demo','team-vision-demo']};
  providerCatalog=[...samples[document.querySelector('#provider-protocol').value]];
  closeModelCandidates();
  document.querySelector('#model-sync-status').textContent='已同步 '+providerCatalog.length+' 个模型（示例） · 在模型 ID 下拉列表中选择或直接填写';
  toast('已模拟同步模型列表，现有模型配置保留');
}
function showModelCandidates(row,query=''){
  closeModelCandidates();const input=row.querySelector('.provider-model-id'),list=row.querySelector('.model-candidates');
  const matches=providerCatalog.filter(id=>id.toLowerCase().includes(query.trim().toLowerCase()));
  list.innerHTML=matches.length?matches.map((id,i)=>`<button type="button" role="option" id="${list.id}-${i}" aria-selected="false" data-action="pick-synced-model" data-model-id="${esc(id)}">${esc(id)}</button>`).join(''):`<div class="model-candidates-empty">${providerCatalog.length?'没有匹配的模型，可继续使用手动填写的 ID。':'请先同步模型列表，也可直接填写 ID。'}</div>`;
  list.hidden=false;input.setAttribute('aria-expanded','true');
}
function chooseSyncedModel(row,id){row.querySelector('.provider-model-id').value=id;syncModelName(row);closeModelCandidates();row.querySelector('.provider-model-id').focus();}
function handleModelPickerClick(e,target){
  if(target?.dataset.action==='toggle-model-list'){const row=target.closest('.provider-model-row');const open=!row.querySelector('.model-candidates').hidden;if(open)closeModelCandidates();else showModelCandidates(row);row.querySelector('.provider-model-id').focus();return true}
  if(target?.dataset.action==='pick-synced-model'){chooseSyncedModel(target.closest('.provider-model-row'),target.dataset.modelId);return true}
  if(!e.target.closest('.model-id-field'))closeModelCandidates();return false;
}
function handleModelPickerKey(e){
  if(!e.target.matches('.provider-model-id'))return false;
  const row=e.target.closest('.provider-model-row'),list=row.querySelector('.model-candidates');
  if(e.key==='Escape'&&!list.hidden){e.preventDefault();closeModelCandidates();return true}
  if(e.key==='Tab'){closeModelCandidates();return false}
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){
    e.preventDefault();if(list.hidden)showModelCandidates(row);
    const options=[...list.querySelectorAll('[role=option]')];if(!options.length)return true;
    const previous=options.findIndex(el=>el.getAttribute('aria-selected')==='true');
    const next=previous<0?(e.key==='ArrowDown'?0:options.length-1):(previous+(e.key==='ArrowDown'?1:options.length-1))%options.length;
    options.forEach((el,i)=>el.setAttribute('aria-selected',String(i===next)));e.target.setAttribute('aria-activedescendant',options[next].id);options[next].scrollIntoView({block:'nearest'});return true;
  }
  if(e.key==='Enter'&&!list.hidden){const selected=list.querySelector('[aria-selected=true]');if(selected){e.preventDefault();chooseSyncedModel(row,selected.dataset.modelId)}return true}
  return false;
}
function modelRow(value='',contextWindow=128000,detail={}){const d={name:'',maxTokens:16384,input:['text'],reasoning:false,...detail};const pickerId='model-candidates-'+(++modelPickerId);return `<div class="provider-model-row"><div class="model-identity-fields"><div class="model-id-field"><label><span>模型 ID <b>*</b></span><input class="provider-model-id" aria-label="模型 ID" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${pickerId}" autocomplete="off" value="${esc(value)}" placeholder="输入或选择模型 ID"></label><button class="model-list-toggle" data-action="toggle-model-list" aria-label="选择同步的模型" title="选择同步的模型">${icon('down')}</button><div class="model-candidates" id="${pickerId}" role="listbox" aria-label="已同步的模型" hidden></div></div><label><span>显示名称</span><input class="provider-model-name" data-auto-name="${!(d.nameCustomized??(!!d.name&&d.name!==value))}" aria-label="模型显示名称" value="${esc(d.name||value)}" placeholder="默认使用模型 ID"></label><button class="iconbtn" data-action="remove-model-row" aria-label="移除模型" title="移除模型">${icon('close')}</button></div><details class="model-capabilities" open><summary>能力与限制</summary><div class="model-capability-toggles"><label class="capability-toggle"><span>支持图片输入</span><input class="provider-model-images" type="checkbox" role="switch" aria-label="支持图片输入" ${d.input.includes('image')?'checked':''}><span class="toggle-track" aria-hidden="true"></span></label></div><div class="model-limit-fields"><label><span>上下文长度 · Tokens <b>*</b></span><input class="provider-context-window" aria-label="上下文长度 Tokens" type="number" min="1" step="1" value="${contextWindow}"></label><label><span>最大输出 Tokens <b>*</b></span><input class="provider-model-output" aria-label="最大输出 Tokens" type="number" min="1" step="1" value="${d.maxTokens}"></label></div><p class="model-limit-help">上下文长度是整体上下文容量，包含输入与输出预算。图片开关声明模型能力，不代表已验证服务支持。</p>${thinkingSettings(d)}</details></div>`}

function providerDialog(i){const p=state.providers[i]||{name:'',models:[''],endpoint:'',protocol:'anthropic-messages'};providerCatalog=[...(p.modelCatalog||[])];modal(i===undefined?'添加 Provider':'编辑 Provider',`<div class="formfield"><label>显示名称</label><input id="provider-name" value="${esc(p.name)}" placeholder="例如：团队 Anthropic 网关"></div><div class="formfield"><label for="provider-protocol">协议类型</label><select id="provider-protocol">${providerProtocols.map(([key,label])=>`<option value="${key}" ${p.protocol===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="formfield"><label>服务地址</label><input id="provider-url" value="${esc(p.endpoint)}" placeholder="https://api.example.com/v1"></div><div class="formfield"><div class="between"><label>模型列表</label><div class="flex">${button('同步模型列表','sync-model-list','sm')}${button('添加模型','add-model-row','sm','plus')}</div></div><small id="model-sync-status" role="status">${providerCatalog.length?'已同步 '+providerCatalog.length+' 个模型（示例）':'可直接填写模型 ID，或同步后从下拉列表选择。'}</small><div id="provider-model-list">${p.models.map(m=>modelRow(m,p.contextWindows?.[m]??128000,modelDetail(p,m))).join('')}</div><small>每个模型独立配置能力与限制。新模型预填上下文 128000、最大输出 16384，请按服务实际支持调整。</small></div><div class="formfield"><label>API Key</label><input type="password" autocomplete="off" placeholder="请勿在原型输入真实凭据"><small>这里只讨论配置界面，不保存或连接模型服务。</small></div>`,button('保存','save-provider:'+(i??'new'),'primary'));document.querySelector('.modal').classList.add('provider-editor')}
