function completions(symbol,q=''){if(taskDirectories().length&&symbol==='@')return task().repos.map(i=>({name:repos[i]+'/README.md',source:'任务 worktree / '+repos[i],type:'file'})).concat(taskDirectories().map(d=>({name:directoryLinkName(d)+'/README.md',source:d.name+' → '+d.path+' · 软链接示例',type:'file'}))).filter(r=>(r.name+' '+r.source).toLowerCase().includes(q.toLowerCase()));let rows=symbol==='@'?task().repos.map(i=>({name:repos[i]+'/README.md',source:'当前任务 / '+repos[i],type:'file'})).concat([{name:'src/detail.ts · 代码片段',source:repos[state.fileRepo],type:'file'}]):symbol==='$'?[{name:'code-review',source:'全局技能',type:'skill'},{name:'tdd',source:'全局技能',type:'skill'},{name:'diagnosing-bugs',source:'项目技能',type:'skill'}]:[['new','新建会话'],['model','切换 Provider / 模型'],['compact','压缩当前上下文'],['skills','查看可用技能'],['session','当前会话信息'],['usage','查看 Token 用量'],['help','查看命令说明']].map(([n,s])=>({name:'/'+n,source:s,type:'command'}));return rows.filter(r=>(r.name+' '+r.source).toLowerCase().includes(q.toLowerCase()))}
