document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(handleModelPickerClick(e,target))return;if(target?.dataset.action==='remove-model-row'){const list=target.closest('#provider-model-list');if(list.children.length>1)target.closest('.provider-model-row').remove();else list.innerHTML=modelRow();return}if(target?.dataset.action==='close-composer-popover'){closeComposerPopover(true);return}if(target)dispatch(target.dataset.action)});
