document.addEventListener('change',e=>{if(e.target.id==='subagent-select'){dispatch('select-subagent:'+e.target.value);return}if(e.target.id==='provider-protocol'){resetModelCatalog();return}if(e.target.matches('.provider-model-name')&&!e.target.value.trim()){syncModelName(e.target.closest('.provider-model-row'));return}if(e.target.matches('.provider-thinking-mode,.provider-thinking-level')){syncThinking(e.target.closest('.provider-model-row'))}else if(e.target.id==='attachment-picker'){const files=[...e.target.files];if(!files.length)return;addComposerAttachments(files);render();document.querySelector('#message-input')?.focus();toast('已添加 '+files.length+' 个附件，仅保留在当前页面')}else if(e.target.id==='environment-select'){state.envId=e.target.value;state.env=currentEnvironment().name;state.envDirty=false;if(task()?.envId!==state.envId)state.envScope='shared';render();toast('已切换配置视图，任务运行环境不会自动改变')}else if(e.target.id==='usage-range'){state.usageRange=e.target.value;render()}else if(e.target.id==='usage-group'){state.usageGroup=e.target.value;render()}else if(e.target.id==='task-switch'){state.task=+e.target.value;render()}});
document.addEventListener('keydown',e=>{if(e.isComposing||e.keyCode===229)return;if(handleModelPickerKey(e))return;if(e.key==='Escape'&&document.querySelector('#composer-popover')){e.preventDefault();closeComposerPopover(true);return}if(e.target.closest('#composer-popover')){const choices=[...document.querySelectorAll('#composer-popover .picker-choice:not(:disabled)')];if(['ArrowDown','ArrowUp'].includes(e.key)&&choices.length){e.preventDefault();const index=choices.indexOf(e.target);choices[index<0?(e.key==='ArrowDown'?0:choices.length-1):(index+(e.key==='ArrowDown'?1:choices.length-1))%choices.length].focus()}else if(e.key==='Enter'&&e.target.id==='conversation-model-search'&&choices.length){e.preventDefault();choices[0].click()}return}if(e.target.id==='message-input'){if(state.completion.length){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();state.completionIndex=(state.completionIndex+(e.key==='ArrowDown'?1:state.completion.length-1))%state.completion.length;drawCompletion();return}if(e.key==='Tab'||(e.key==='Enter'&&!e.shiftKey)){e.preventDefault();chooseCompletion(state.completionIndex);return}if(e.key==='Escape'){state.completion=[];drawCompletion();return}}if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}return}if(e.target.id==='terminal-input'&&e.key==='Enter'){e.preventDefault();if(sessionReadonly()){toast('只读会话不能操作终端');return}const row=document.createElement('div');row.textContent='$ '+e.target.value+'\n[模拟回显，不执行]';document.querySelector('#terminal-output').appendChild(row);e.target.value='';return}if(e.key==='Escape'){closeModal();return}if(e.target.closest('input,textarea,select,[contenteditable]')||document.querySelector('.modal'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();dispatch(e.key==='ArrowLeft'?'variant-prev':'variant-next')}if(e.key==='Enter'&&e.target.matches('[role=button]'))dispatch(e.target.dataset.action)});
